import json
import csv

def get_cvss_score(v):
    cvss = v.get('CVSS', {})
    # Prefer ghsa, then nvd, then redhat, then first available
    for source in ['ghsa', 'nvd', 'redhat']:
        if source in cvss:
            return cvss[source].get('V3Score', 'N/A')
    for source in cvss:
        return cvss[source].get('V3Score', 'N/A')
    return 'N/A'

with open('/root/trivy_report.json', 'r') as f:
    data = json.load(f)

vulnerabilities = []
if 'Results' in data:
    for result in data['Results']:
        if 'Vulnerabilities' in result:
            for v in result['Vulnerabilities']:
                pkg_name = v.get('PkgName', 'N/A')
                version = v.get('InstalledVersion', 'N/A')
                cve_id = v.get('VulnerabilityID', 'N/A')
                severity = v.get('Severity', 'N/A')
                cvss_score = get_cvss_score(v)
                fixed_version = v.get('FixedVersion', 'N/A')
                title = v.get('Title', 'N/A').replace('\n', ' ').replace('\r', ' ')
                url = v.get('PrimaryURL', 'N/A')

                vulnerabilities.append([
                    pkg_name, version, cve_id, severity, cvss_score, fixed_version, title, url
                ])

with open('/root/security_audit.csv', 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score', 'Fixed_Version', 'Title', 'Url'])
    writer.writerows(vulnerabilities)
